package dev.celerbi.easyfarmersdelightcompat.integration.jei;
import dev.celerbi.easyfarmersdelightcompat.integration.CutterAxeInfo;import dev.celerbi.easyfarmersdelightcompat.registry.ModBlocks;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.IFocusGroup;import mezz.jei.api.recipe.RecipeIngredientRole;import mezz.jei.api.recipe.RecipeType;import mezz.jei.api.recipe.category.IRecipeCategory;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.world.item.ItemStack;
public final class CutterAxeJeiCategory implements IRecipeCategory<CutterAxeInfo>{private final IDrawable icon;public CutterAxeJeiCategory(IGuiHelper g){icon=g.createDrawableItemStack(new ItemStack(ModBlocks.CUTTER_ITEM.get()));}public RecipeType<CutterAxeInfo> getRecipeType(){return EasyFdJeiPlugin.CUTTER_AXE;}public Component getTitle(){return Component.translatable("jei.easyfarmersdelightcompat.cutter_axe");}public IDrawable getIcon(){return icon;}public int getWidth(){return 150;}public int getHeight(){return 58;}public void setRecipe(IRecipeLayoutBuilder b,CutterAxeInfo r,IFocusGroup f){b.addInputSlot(12,8).addItemStack(r.input());b.addSlot(RecipeIngredientRole.CATALYST,50,8).addIngredients(r.tool());b.addOutputSlot(116,8).addItemStack(r.output());}public void draw(CutterAxeInfo r,IRecipeSlotsView v,GuiGraphics g,double mx,double my){var font=Minecraft.getInstance().font;g.drawString(font,"+",38,13,0x404040,false);g.drawString(font,"→",88,13,0x404040,false);g.drawString(font,r.description(),8,36,0x555555,false);}}
